Contract LibraryManagementSystemSystem::makeReservation(uid:String,barcode:String): Boolean {
          definition:
          obsUser:User = User.allInstance()->any(u | u.UserID = uid), obsCopy:BookCopy = BookCopy.allInstance()->any(c | c.Barcode = barcode)

            precondition:
          obsUser.oclIsUndefined() = false and obsCopy.oclIsUndefined() = false and obsUser.BorrowStatus = BorrowStatus[NORMAL] and obsCopy.Status = CopyStatus[AVAILABLE]

            postcondition:
          let res:Reserve in res.oclIsNew() and res.ReservedUser = obsUser and res.ReservedCopy = obsCopy and Reserve.allInstance()->includes(res) and result = res.oclIsNew()

        }
